// 1. Allocate GPU staging buffer with MAP_READ capability
const stagingBuffer = device.createBuffer({
    size: bytesPerRow * height,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ
});

// 2. Encode GPU texture copy
commandEncoder.copyTextureToBuffer(
    { texture: canvasTexture },
    { buffer: stagingBuffer, bytesPerRow, rowsPerImage: height },
    { width, height, depthOrArrayLayers: 1 }
);
device.queue.submit([commandEncoder.finish()]);

// 3. Map buffer asynchronously to CPU memory
await stagingBuffer.mapAsync(GPUMapMode.READ);
const mappedArray = new Uint8Array(stagingBuffer.getMappedRange());

// 4. Strip padding bytes if unalignedBytesPerRow !== bytesPerRow
const tightPixels = removeRowPadding(mappedArray, width, height, bytesPerRow);

// 5. Send to encoder and release VRAM
stagingBuffer.unmap();
stagingBuffer.destroy();

// Capture current scene as lossless PNG
  await snapshotManager.capture({
